window.GIBDD_DATA = {"id":"gibdd","title":"ФЗ о ГИБДД","full_title":"ФЕДЕРАЛЬНЫЙ ЗАКОН«О ГОСУДАРСТВЕННОЙ ИНСПЕКЦИИ БЕЗОПАСНОСТИ ДОРОЖНОГО ДВИЖЕНИЯ»","revision":"25.08.2026","source_url":"https://forum.russia.online/threads/federal-nyi-zakon-o-gosudarstvennoi-inspektsii-bezopasnosti-dorozhnogo-dvizheniya.5250/","post_id":"post-17302","preamble":"ФЕДЕРАЛЬНЫЙ ЗАКОН «О ГОСУДАРСТВЕННОЙ ИНСПЕКЦИИ БЕЗОПАСНОСТИ ДОРОЖНОГО ДВИЖЕНИЯ»​ Настоящий Федеральный закон определяет статус, задачи, систему, полномочия и порядок деятельности Государственной инспекции безопасности дорожного движения, особенности государственного надзора в области дорожного движения, права и обязанности сотрудников ГИБДД, порядок остановки транспортных средств, освидетельствования водителей, оформления дорожно-транспортных происшествий, задержания и перемещения транспортных средств, регистрации транспортных средств и выдачи водительских удостоверений, а также формы взаимодействия ГИБДД с иными государственными органами.","signature":"Нормативно-правовой акт подписан Премьер-министром РО 25.08.2026 Марк Брагин ​","type_detected":"A","nodes":[{"type":"chapter","number":"I","title":"ОБЩИЕ ПОЛОЖЕНИЯ​","children":[{"type":"article","number":"1","title":"Государственная инспекция безопасности дорожного движения","children":[{"type":"paragraph","number":"1","text":"Государственная инспекция безопасности дорожного движения РО (далее — ГИБДД) является специализированным подразделением полиции в системе Министерства внутренних дел РО, осуществляющим государственный надзор, административную и правоохранительную деятельность в области безопасности дорожного движения."},{"type":"paragraph","number":"2","text":"ГИБДД действует на всей территории РО в пределах полномочий, установленных настоящим Федеральным законом, Федеральным законом «О полиции», Кодексом РО об административных правонарушениях, Процессуальным кодексом РО и иными федеральными законами."},{"type":"paragraph","number":"3","text":"ГИБДД обладает самостоятельной служебной компетенцией по вопросам безопасности дорожного движения и не подменяет иные подразделения МВД РО, прокуратуру, Следственный комитет РО, Федеральную службу безопасности РО или суд."}],"node_id":"1"},{"type":"article","number":"2","title":"Правовая основа деятельности ГИБДД","children":[{"type":"paragraph","number":"1","text":"Правовую основу деятельности ГИБДД составляют Конституция РО, федеральные конституционные законы, федеральные кодексы, Федеральный закон «О полиции», настоящий Федеральный закон и иные федеральные законы."},{"type":"paragraph","number":"2","text":"Акты Премьер-министра РО, Правительства РО, Министерства внутренних дел РО и внутренние акты ГИБДД применяются в части, не противоречащей актам большей юридической силы."},{"type":"paragraph","number":"3","text":"Внутренний акт не может самостоятельно создавать состав административного правонарушения, устанавливать наказание, новое основание остановки, обыска, лишения права управления либо иное ограничение прав граждан."}],"node_id":"2"},{"type":"article","number":"3","title":"Основные задачи ГИБДД","children":[{"type":"paragraph","text":"Основными задачами ГИБДД являются:","children":[{"type":"subparagraph","number":"1","text":"обеспечение безопасности дорожного движения;"},{"type":"subparagraph","number":"2","text":"предупреждение, выявление и пресечение правонарушений в области дорожного движения;"},{"type":"subparagraph","number":"3","text":"регулирование дорожного движения и устранение непосредственных угроз его безопасности;"},{"type":"subparagraph","number":"4","text":"производство по делам об административных правонарушениях в пределах компетенции; 5) оформление дорожно-транспортных происшествий;"},{"type":"subparagraph","number":"6","text":"выявление водителей, не имеющих права управления либо находящихся в состоянии опьянения;"},{"type":"subparagraph","number":"7","text":"государственная регистрация транспортных средств и ведение соответствующего учета;"},{"type":"subparagraph","number":"8","text":"организация выдачи водительских удостоверений;"},{"type":"subparagraph","number":"9","text":"контроль технического состояния транспортных средств в предусмотренных законом случаях;"},{"type":"subparagraph","number":"10","text":"контроль законности использования специальных световых и звуковых сигналов;"},{"type":"subparagraph","number":"11","text":"участие в розыске транспортных средств и лиц;"},{"type":"subparagraph","number":"12","text":"обеспечение безопасного движения организованных колонн, специальных перевозок и государственных мероприятий."}]}],"node_id":"3"},{"type":"article","number":"4","title":"Принципы деятельности ГИБДД","children":[{"type":"paragraph","text":"Деятельность ГИБДД основывается на законности, уважении прав и свобод человека, необходимости и соразмерности государственного вмешательства, беспристрастности, приоритете сохранения жизни и здоровья участников дорожного движения, открытости в допустимом законом объеме, персональной ответственности сотрудника и недопустимости необоснованного затягивания проверки или остановки транспортного средства."}],"node_id":"4"},{"type":"article","number":"5","title":"Соотношение с Федеральным законом «О полиции»","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД является сотрудником полиции и обладает общими правами, обязанностями, гарантиями и ответственностью сотрудника полиции."},{"type":"paragraph","number":"2","text":"Правила о законных требованиях, задержании, обыске, применении физической силы, специальных средств и огнестрельного оружия применяются к сотрудникам ГИБДД в соответствии с Федеральным законом «О полиции» и процессуальным законодательством."},{"type":"paragraph","number":"3","text":"Настоящий Федеральный закон устанавливает специальные дорожные полномочия, которые дополняют общие полномочия полиции."}],"node_id":"5"},{"type":"article","number":"6","title":"Правила дорожного движения","children":[{"type":"paragraph","number":"1","text":"Единые обязательные правила дорожного движения утверждаются Правительством РО."},{"type":"paragraph","number":"2","text":"Правила дорожного движения определяют обязанности водителей, пешеходов и иных участников движения, значение сигналов светофоров и регулировщика, дорожных знаков и разметки, порядок маневрирования, движения по полосам, проезда перекрестков, остановки и стоянки, использования внешних световых приборов, перевозки пассажиров и грузов и иные правила безопасного движения."},{"type":"paragraph","number":"3","text":"Административная ответственность за нарушение правил дорожного движения устанавливается Кодексом РО об административных правонарушениях, а не Правилами дорожного движения или внутренними актами ГИБДД."}],"node_id":"6"},{"type":"article","number":"7","title":"Территориальность и непрерывность дорожного надзора","children":[{"type":"paragraph","number":"1","text":"Сотрудники ГИБДД вправе осуществлять дорожный надзор на автомобильных дорогах, улицах, площадях, парковках общего пользования и иных территориях, на которых осуществляется движение транспортных средств."},{"type":"paragraph","number":"2","text":"Территориальное распределение подразделений не препятствует сотруднику пресечь очевидное дорожное правонарушение, оказать помощь, остановить опасное транспортное средство либо оформить происшествие вне обычного участка несения службы."},{"type":"paragraph","number":"3","text":"После совершения неотложных действий материал при необходимости передается компетентному подразделению."}],"node_id":"7"},{"type":"article","number":"8","title":"Пределы вмешательства в дорожное движение","children":[{"type":"paragraph","number":"1","text":"Любое требование, остановка, ограничение движения, досмотр, эвакуация или иная мера должны иметь конкретное законное основание и применяться только в объеме, необходимом для достижения законной цели."},{"type":"paragraph","number":"2","text":"Остановка транспортного средства не может использоваться исключительно для унижения водителя, создания необоснованной задержки, личного конфликта либо получения сведений, не связанных со служебной необходимостью."}],"node_id":"8"}]},{"type":"chapter","number":"II","title":"СИСТЕМА ГИБДД И РУКОВОДСТВО​","children":[{"type":"article","number":"9","title":"Система ГИБДД","children":[{"type":"paragraph","number":"1","text":"В систему ГИБДД входят центральное руководство, территориальные подразделения, дорожно-патрульные подразделения, регистрационно-экзаменационные подразделения, подразделения технического надзора и иные структурные подразделения, создаваемые в пределах задач настоящего Федерального закона."},{"type":"paragraph","number":"2","text":"Внутренняя структура определяется Начальником ГИБДД в пределах общей организационной структуры Министерства внутренних дел РО."},{"type":"paragraph","number":"3","text":"Наименование подразделения само по себе не создает дополнительных властных полномочий."}],"node_id":"9"},{"type":"article","number":"10","title":"Начальник ГИБДД","children":[{"type":"paragraph","number":"1","text":"ГИБДД возглавляет Начальник Государственной инспекции безопасности дорожного движения РО."},{"type":"paragraph","number":"2","text":"Начальник ГИБДД назначается на должность и освобождается от должности Федеральным Правительством."},{"type":"paragraph","number":"3","text":"Срок полномочий Начальника ГИБДД составляет тридцать календарных дней. Допускается повторное назначение на последующие сроки."},{"type":"paragraph","number":"4","text":"Первоначальное специальное звание и последующее возможное повышение Начальника ГИБДД определяются Федеральным законом «О специальных и воинских званиях и классных чинах»."}],"node_id":"10"},{"type":"article","number":"11","title":"Подчиненность ГИБДД","children":[{"type":"paragraph","number":"1","text":"Министр внутренних дел РО осуществляет общее государственное и организационное руководство ГИБДД как частью системы Министерства внутренних дел."},{"type":"paragraph","number":"2","text":"Непосредственное оперативное и служебное руководство ГИБДД осуществляет Начальник ГИБДД."},{"type":"paragraph","number":"3","text":"Руководитель Главного управления МВД РО и Начальник ГИБДД взаимодействуют как руководители самостоятельных направлений полицейской службы. Руководитель Главного управления МВД РО не вправе отменять решения Начальника ГИБДД по вопросам специальной дорожной компетенции, если такое полномочие прямо не предоставлено федеральным законом или актом Министра внутренних дел, изданным в пределах его компетенции."}],"node_id":"11"},{"type":"article","number":"12","title":"Полномочия Начальника ГИБДД","children":[{"type":"paragraph","text":"Начальник ГИБДД:","children":[{"type":"subparagraph","number":"1","text":"организует деятельность ГИБДД;"},{"type":"subparagraph","number":"2","text":"определяет внутреннюю структуру и распределяет компетенцию;"},{"type":"subparagraph","number":"3","text":"назначает и освобождает сотрудников в пределах полномочий;"},{"type":"subparagraph","number":"4","text":"утверждает планы дорожного надзора и специальных мероприятий;"},{"type":"subparagraph","number":"5","text":"издает обязательные для сотрудников приказы и инструкции;"},{"type":"subparagraph","number":"6","text":"осуществляет ведомственный контроль;"},{"type":"subparagraph","number":"7","text":"организует регистрационно-экзаменационную деятельность;"},{"type":"subparagraph","number":"8","text":"обеспечивает взаимодействие с МВД РО, прокуратурой, Следственным комитетом, ФСБ РО, судами, Вооруженными Силами, медицинскими и дорожными службами;"},{"type":"subparagraph","number":"9","text":"принимает решения о длительных или масштабных ограничениях дорожного движения в случаях, предусмотренных законом;"},{"type":"subparagraph","number":"10","text":"осуществляет иные полномочия, установленные федеральным законодательством."}]}],"node_id":"12"},{"type":"article","number":"13","title":"Заместитель Начальника ГИБДД","children":[{"type":"paragraph","number":"1","text":"Заместитель Начальника ГИБДД назначается и освобождается Начальником ГИБДД, если иной порядок не установлен актом Правительства РО или Министра внутренних дел."},{"type":"paragraph","number":"2","text":"Заместитель руководит порученными направлениями и замещает Начальника ГИБДД на основании официального акта."},{"type":"paragraph","number":"3","text":"Временное исполнение обязанностей Начальника ГИБДД не считается самостоятельным сроком полномочий для целей присвоения высшего специального звания."}],"node_id":"13"},{"type":"article","number":"14","title":"Сотрудники ГИБДД и специальные звания","children":[{"type":"paragraph","number":"1","text":"Сотрудники ГИБДД проходят службу в полиции и имеют специальные звания полиции."},{"type":"paragraph","number":"2","text":"Предельные звания по должностям, порядок присвоения, повышения, понижения и сохранения званий определяются Федеральным законом «О специальных и воинских званиях и классных чинах»."},{"type":"paragraph","number":"3","text":"Перевод между ГИБДД и иными подразделениями МВД РО осуществляется с сохранением специального звания с учетом предельного звания новой должности."}],"node_id":"14"},{"type":"article","number":"15","title":"Служебное удостоверение, нагрудный знак и идентификация сотрудника","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД обязан иметь служебное удостоверение и индивидуальный служебный номер."},{"type":"paragraph","number":"2","text":"При обращении к водителю или иному участнику дорожного движения сотрудник обязан представиться в порядке Федерального закона «О полиции» и по требованию сообщить причину обращения или остановки, если немедленное сообщение не создает угрозу безопасности и не препятствует законной операции."},{"type":"paragraph","number":"3","text":"При назначении административного наказания, проведении освидетельствования, досмотра, задержания транспортного средства либо ином существенном ограничении прав сотрудник обязан быть идентифицируем при первой безопасной возможности."}],"node_id":"15"},{"type":"article","number":"16","title":"Внутренние акты ГИБДД","children":[{"type":"paragraph","number":"1","text":"Начальник ГИБДД вправе издавать приказы, инструкции и регламенты по вопросам патрулирования, несения службы, оформления материалов, использования технических средств, учета, регистрации, экзаменационной деятельности и внутренней дисциплины."},{"type":"paragraph","number":"2","text":"Внутренний акт не может расширять основания остановки, обыска, задержания, лишения права управления или административной ответственности сверх федерального законодательства."}],"node_id":"16"}]},{"type":"chapter","number":"III","title":"ДОРОЖНЫЙ НАДЗОР И ОСТАНОВКА ТРАНСПОРТНЫХ СРЕДСТВ​","children":[{"type":"article","number":"17","title":"Дорожно-патрульная деятельность","children":[{"type":"paragraph","number":"1","text":"ГИБДД осуществляет патрулирование дорог, наблюдение за движением, реагирование на сообщения о нарушениях и происшествиях, регулирование движения и иные меры дорожного надзора."},{"type":"paragraph","number":"2","text":"Патрулирование может осуществляться на служебных транспортных средствах, пешими нарядами, стационарными постами и иными законными способами."},{"type":"paragraph","number":"3","text":"Использование частного транспортного средства для обычного несения патрульной службы не допускается, если иное не предусмотрено федеральным законом для неотложного случая."}],"node_id":"17"},{"type":"article","number":"18","title":"Право сотрудника ГИБДД требовать остановку транспортного средства","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД вправе заявить водителю обязательное требование об остановке транспортного средства при наличии основания, предусмотренного настоящим Федеральным законом."},{"type":"paragraph","number":"2","text":"Требование должно быть однозначным и доведено способом, позволяющим водителю разумно понять, что оно исходит от сотрудника ГИБДД: жестом, сигналом специального устройства, громкоговорителем, световым сигналом служебного транспортного средства либо иным ясно воспринимаемым способом."},{"type":"paragraph","number":"3","text":"Водитель обязан остановиться в ближайшем месте, где остановка может быть выполнена без создания явно большей опасности."}],"node_id":"18"},{"type":"article","number":"19","title":"Основания остановки транспортного средства","children":[{"type":"paragraph","text":"Сотрудник ГИБДД вправе остановить транспортное средство:","children":[{"type":"subparagraph","number":"1","text":"при непосредственном выявлении либо технической фиксации признаков дорожного правонарушения;"},{"type":"subparagraph","number":"2","text":"для проверки права управления, регистрационных документов и государственных регистрационных знаков в рамках дорожного надзора;"},{"type":"subparagraph","number":"3","text":"при наличии ориентировки, розыска или сведений о причастности транспортного средства либо находящегося в нем лица к правонарушению;"},{"type":"subparagraph","number":"4","text":"при наличии внешних признаков технической неисправности, создающей угрозу безопасности;"},{"type":"subparagraph","number":"5","text":"при наличии признаков опьянения, заболевания или иного состояния водителя, исключающего безопасное управление;"},{"type":"subparagraph","number":"6","text":"при проведении законно установленного контрольного поста, заградительного мероприятия или специальной профилактической операции;"},{"type":"subparagraph","number":"7","text":"для регулирования движения, обеспечения проезда специального транспорта, организованной колонны либо охраняемого мероприятия;"},{"type":"subparagraph","number":"8","text":"при ДТП или наличии оснований полагать, что транспортное средство связано с ДТП;"},{"type":"subparagraph","number":"9","text":"для предотвращения непосредственной угрозы жизни и здоровью;"},{"type":"subparagraph","number":"10","text":"в иных случаях, прямо предусмотренных федеральным законом."}]}],"node_id":"19"},{"type":"article","number":"20","title":"Порядок остановки транспортного средства","children":[{"type":"paragraph","number":"1","text":"После остановки сотрудник без необоснованного промедления сообщает водителю причину остановки и предъявляет требования, относящиеся к установленному основанию."},{"type":"paragraph","number":"2","text":"Обычная проверка не должна длиться дольше времени, объективно необходимого для установления личности водителя, проверки документов, сведений учета и разрешения выявленного материала."},{"type":"paragraph","number":"3","text":"Если первоначальное основание не подтвердилось и отсутствует другое самостоятельное законное основание, дальнейшее удержание водителя и транспортного средства прекращается."}],"node_id":"20"},{"type":"article","number":"21","title":"Требование водителю или пассажиру покинуть транспортное средство","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД вправе потребовать от водителя покинуть транспортное средство, если необходимо:","children":[{"type":"subparagraph","number":"1","text":"отстранить его от управления;"},{"type":"subparagraph","number":"2","text":"провести законное освидетельствование;"},{"type":"subparagraph","number":"3","text":"задержать или установить личность лица;"},{"type":"subparagraph","number":"4","text":"произвести предусмотренный законом осмотр, досмотр или обыск;"},{"type":"subparagraph","number":"5","text":"проверить идентификационные обозначения или техническое состояние, когда это невозможно безопасно сделать иным способом;"},{"type":"subparagraph","number":"6","text":"устранить непосредственную угрозу безопасности;"},{"type":"subparagraph","number":"7","text":"исполнить иной процессуальный акт."}]},{"type":"paragraph","number":"2","text":"Пассажиру может быть предъявлено такое требование при его задержании, необходимости обеспечить безопасность, проведении процессуального действия либо наличии иной предусмотренной законом причины."},{"type":"paragraph","number":"3","text":"Отказ выйти из транспортного средства сам по себе не является основанием для применения смертельной силы."}],"node_id":"21"},{"type":"article","number":"22","title":"Проверка документов водителя и транспортного средства","children":[{"type":"paragraph","number":"1","text":"При законной остановке сотрудник ГИБДД вправе потребовать предъявить водительское удостоверение соответствующей категории, регистрационные документы на транспортное средство и иные документы, обязанность иметь которые прямо установлена федеральным законодательством."},{"type":"paragraph","number":"2","text":"Документы могут быть проверены по государственным информационным системам."},{"type":"paragraph","number":"3","text":"Сотрудник не вправе удерживать документ после окончания проверки без самостоятельного законного основания для его изъятия или исполнения решения о лишении специального права."}],"node_id":"22"},{"type":"article","number":"23","title":"Проверка государственных регистрационных знаков и идентификационных обозначений","children":[{"type":"paragraph","number":"1","text":"ГИБДД вправе проверять соответствие государственного регистрационного знака сведениям государственного учета, а также идентификационные обозначения транспортного средства при наличии необходимости подтвердить регистрацию или признаки подделки."},{"type":"paragraph","number":"2","text":"Проверка идентификационного обозначения не должна превращаться в полный обыск транспортного средства без самостоятельного процессуального основания."},{"type":"paragraph","number":"3","text":"При выявлении признаков подложного регистрационного знака или изменения идентификационного обозначения сотрудник принимает меры, предусмотренные Кодексом РО об административных правонарушениях и процессуальным законодательством."}],"node_id":"23"},{"type":"article","number":"24","title":"Осмотр и обыск транспортного средства","children":[{"type":"paragraph","number":"1","text":"Визуальный осмотр внешнего состояния транспортного средства, регистрационных знаков, открыто видимых предметов и груза допускается в рамках законной дорожной проверки."},{"type":"paragraph","number":"2","text":"Открытие закрытых отсеков, обследование личных вещей и иные действия, направленные на принудительный поиск скрытых предметов, являются процессуальным обыском и допускаются только по основаниям и в порядке Процессуального кодекса РО."},{"type":"paragraph","number":"3","text":"Отсутствие регистрационного знака, нарушение правил остановки или обычное превышение скорости сами по себе не создают основания для полного обыска транспортного средства."}],"node_id":"24"},{"type":"article","number":"25","title":"Использование технических средств дорожного надзора","children":[{"type":"paragraph","number":"1","text":"ГИБДД вправе использовать средства фото- и видеофиксации, измерения скорости, проверки регистрационных знаков, определения технического состояния и иные законно допущенные технические средства."},{"type":"paragraph","number":"2","text":"Результат технического средства используется как доказательство при возможности установить относимость результата к конкретному транспортному средству, время и существенные обстоятельства фиксации."},{"type":"paragraph","number":"3","text":"Сотрудник обязан учитывать очевидную техническую ошибку и не вправе сознательно основывать решение на заведомо недостоверном измерении."}],"node_id":"25"},{"type":"article","number":"26","title":"Регулирование дорожного движения","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД вправе вручную регулировать дорожное движение, временно изменять очередность проезда, запрещать или разрешать движение по отдельному направлению, если это необходимо для безопасности, ликвидации последствий ДТП, пропуска экстренного транспорта, проведения законной операции или устранения иной угрозы."},{"type":"paragraph","number":"2","text":"Сигналы регулировщика обязательны для участников движения и имеют приоритет перед обычным режимом светофора, знака или разметки в пределах регулируемого участка."},{"type":"paragraph","number":"3","text":"Ограничение прекращается после отпадения основания."}],"node_id":"26"},{"type":"article","number":"27","title":"Временное ограничение или прекращение движения","children":[{"type":"paragraph","number":"1","text":"ГИБДД вправе временно ограничить или прекратить движение на участке дороги при ДТП, пожаре, аварии, опасном повреждении дорожного полотна, обнаружении опасного предмета, массовых беспорядках, проведении процессуального действия, розыске опасного лица, государственном мероприятии либо иной непосредственной угрозе."},{"type":"paragraph","number":"2","text":"Ограничение должно быть территориально и по времени соразмерно законной цели."},{"type":"paragraph","number":"3","text":"Длительное плановое перекрытие осуществляется по решению Начальника ГИБДД, его заместителя либо иного уполномоченного руководителя, если федеральным законом не установлен другой порядок."}],"node_id":"27"}]},{"type":"chapter","number":"IV","title":"ПРОИЗВОДСТВО ПО ДЕЛАМ ОБ АДМИНИСТРАТИВНЫХ ПРАВОНАРУШЕНИЯХ​","children":[{"type":"article","number":"28","title":"Административная компетенция ГИБДД","children":[{"type":"paragraph","number":"1","text":"ГИБДД возбуждает, рассматривает и разрешает дела обо всех административных правонарушениях, отнесенных Кодексом РО об административных правонарушениях к ее компетенции."},{"type":"paragraph","number":"2","text":"ГИБДД также рассматривает материалы по статье 10 Кодекса РО об административных правонарушениях в пределах установленной этим Кодексом подведомственности."},{"type":"paragraph","number":"3","text":"Если вопрос отнесен к исключительной компетенции суда или прокуратуры, ГИБДД пресекает нарушение, собирает и сохраняет доказательства и передает материал компетентному органу."}],"node_id":"28"},{"type":"article","number":"29","title":"Упрощенное рассмотрение дорожного правонарушения на месте","children":[{"type":"paragraph","number":"1","text":"При дорожном правонарушении и наличии достаточных доказательств сотрудник вправе разрешить материал непосредственно на месте в порядке Кодекса РО об административных правонарушениях."},{"type":"paragraph","number":"2","text":"До назначения наказания лицу сообщаются существо правонарушения, применяемая статья, основные доказательства, назначаемая мера и право обжалования."},{"type":"paragraph","number":"3","text":"Отдельное письменное дело не требуется, когда Кодекс допускает упрощенное рассмотрение и материалы обязательной фиксации позволяют впоследствии проверить законность решения."}],"node_id":"29"},{"type":"article","number":"30","title":"Составление и передача административного материала","children":[{"type":"paragraph","number":"1","text":"Если материал требует судебного или прокурорского разрешения, сложного исследования обстоятельств либо не может быть законно разрешен на месте, сотрудник оформляет и сохраняет необходимые материалы и передает их компетентному органу."},{"type":"paragraph","number":"2","text":"Передача материала не прекращает обязанность обеспечить сохранность доказательств и, при наличии законного основания, примененных мер обеспечения."}],"node_id":"30"},{"type":"article","number":"31","title":"Лишение права управления транспортными средствами","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД не вправе самостоятельно назначать лишение права управления транспортными средствами, если Кодекс РО об административных правонарушениях относит эту меру к компетенции суда."},{"type":"paragraph","number":"2","text":"При наличии основания для лишения права управления ГИБДД оформляет материал и направляет его мировому судье либо в иной компетентный суд."},{"type":"paragraph","number":"3","text":"ГИБДД исполняет вступивший в силу судебный акт о лишении права управления, в том числе вносит сведения в государственный учет и принимает водительское удостоверение, если это необходимо для исполнения решения."}],"node_id":"31"},{"type":"article","number":"32","title":"Ведомственный пересмотр решения сотрудника ГИБДД","children":[{"type":"paragraph","number":"1","text":"Лицо, привлеченное сотрудником ГИБДД к административной ответственности во внесудебном порядке, вправе потребовать пересмотра решения вышестоящим должностным лицом ГИБДД."},{"type":"paragraph","number":"2","text":"Пересмотр производится в порядке статьи 9.5 Кодекса РО об административных правонарушениях."},{"type":"paragraph","number":"3","text":"Сотрудник, вынесший первоначальное решение, обязан по требованию вышестоящего должностного лица предоставить все доказательства и материалы в установленный Кодексом срок."}],"node_id":"32"},{"type":"article","number":"33","title":"Обязательная фиксация административных действий","children":[{"type":"paragraph","number":"1","text":"Остановка транспортного средства сама по себе не требует непрерывной отдельной записи во всех случаях, однако назначение административного ареста, принудительный обыск, освидетельствование на состояние опьянения, принудительное изъятие, применение силы и иные действия, для которых федеральное законодательство устанавливает обязательную видеофиксацию, подлежат фиксации в установленном порядке."},{"type":"paragraph","number":"2","text":"При вынесении дорожного административного решения сотрудник обязан сохранить относящиеся к нему материалы в объеме и срок, позволяющие осуществить ведомственный, прокурорский или судебный пересмотр."}],"node_id":"33"},{"type":"article","number":"34","title":"Административная ответственность государственного служащего","children":[{"type":"paragraph","number":"1","text":"Если дорожное правонарушение совершено государственным служащим вне связи с исполнением должностных обязанностей и не требует административного ареста, материал рассматривается на общих основаниях."},{"type":"paragraph","number":"2","text":"Если правонарушение связано с исполнением государственных обязанностей либо возникает вопрос об административном аресте действующего государственного служащего, применяется специальный прокурорский порядок, установленный федеральным законодательством."}],"node_id":"34"}]},{"type":"chapter","number":"V","title":"ОТСТРАНЕНИЕ ОТ УПРАВЛЕНИЯ И ОСВИДЕТЕЛЬСТВОВАНИЕ​","children":[{"type":"article","number":"35","title":"Отстранение от управления транспортным средством","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД вправе отстранить лицо от управления, если имеются достаточные основания полагать, что оно:","children":[{"type":"subparagraph","number":"1","text":"не имеет права управления соответствующей категорией;"},{"type":"subparagraph","number":"2","text":"находится в состоянии опьянения;"},{"type":"subparagraph","number":"3","text":"находится в физическом или психическом состоянии, явно исключающем безопасное управление;"},{"type":"subparagraph","number":"4","text":"использует транспортное средство, дальнейшая эксплуатация которого представляет непосредственную угрозу;"},{"type":"subparagraph","number":"5","text":"подлежит задержанию;"},{"type":"subparagraph","number":"6","text":"лишено права управления действующим судебным актом."}]},{"type":"paragraph","number":"2","text":"Отстранение действует только до отпадения основания либо принятия предусмотренного законом решения."}],"node_id":"35"},{"type":"article","number":"36","title":"Основания освидетельствования на состояние опьянения","children":[{"type":"paragraph","number":"1","text":"Освидетельствование допускается при наличии конкретных признаков возможного опьянения либо иных достаточных оснований, связанных с поведением водителя или обстоятельствами управления."},{"type":"paragraph","number":"2","text":"К таким признакам могут относиться запах алкоголя, выраженное нарушение речи или координации, неадекватное поведение, признаки употребления наркотического вещества, опасное или хаотичное управление, а также обстоятельства ДТП, объективно указывающие на необходимость проверки."},{"type":"paragraph","number":"3","text":"Освидетельствование не может проводиться исключительно из любопытства либо в качестве наказания."}],"node_id":"36"},{"type":"article","number":"37","title":"Порядок освидетельствования","children":[{"type":"paragraph","number":"1","text":"Освидетельствование проводится уполномоченным сотрудником с применением допущенного технического средства либо уполномоченным медицинским работником в предусмотренной законом форме."},{"type":"paragraph","number":"2","text":"До начала процедуры водителю сообщаются основание освидетельствования и правовые последствия отказа."},{"type":"paragraph","number":"3","text":"Существенный ход освидетельствования и его результат подлежат видеофиксации, если техническая возможность не утрачена по объективной причине."},{"type":"paragraph","number":"4","text":"При спорном результате, заявленном несогласии либо объективной невозможности надежно провести проверку на месте водитель вправе требовать дополнительного медицинского освидетельствования, если оно доступно и может быть проведено без неоправданной задержки."}],"node_id":"37"},{"type":"article","number":"38","title":"Отказ от освидетельствования","children":[{"type":"paragraph","number":"1","text":"Отказом признается ясно выраженный отказ выполнить законно назначенное освидетельствование после разъяснения основания и последствий."},{"type":"paragraph","number":"2","text":"Физическая невозможность выполнить конкретный способ проверки не признается отказом, если лицо добросовестно предлагает пройти иной предусмотренный законом способ освидетельствования."},{"type":"paragraph","number":"3","text":"Материал об отказе оформляется ГИБДД и направляется в суд, когда санкция предусматривает лишение права управления или иной вопрос исключительной судебной компетенции."}],"node_id":"38"},{"type":"article","number":"39","title":"Последствия выявления состояния опьянения","children":[{"type":"paragraph","number":"1","text":"Водитель, в отношении которого имеются достаточные доказательства состояния опьянения, отстраняется от управления."},{"type":"paragraph","number":"2","text":"Транспортное средство задерживается или передается иному трезвому лицу, имеющему право управления и законное основание владеть или пользоваться транспортным средством, если такое устранение основания допускается Кодексом РО об административных правонарушениях."},{"type":"paragraph","number":"3","text":"Административный материал разрешается или передается в суд в соответствии с Кодексом РО об административных правонарушениях."}],"node_id":"39"},{"type":"article","number":"40","title":"Употребление вызывающих опьянение веществ после ДТП или остановки","children":[{"type":"paragraph","text":"До завершения необходимого освидетельствования либо принятия сотрудником решения об отсутствии оснований для него водитель не вправе употреблять алкогольные, наркотические или иные вызывающие опьянение вещества после ДТП, участником которого он являлся, либо после законной остановки транспортного средства в обстоятельствах, требующих проверки состояния."}],"node_id":"40"}]},{"type":"chapter","number":"VI","title":"ЗАДЕРЖАНИЕ, ЭВАКУАЦИЯ, РЕГИСТРАЦИЯ И ТЕХНИЧЕСКИЙ НАДЗОР​","children":[{"type":"article","number":"41","title":"Задержание транспортного средства","children":[{"type":"paragraph","number":"1","text":"ГИБДД вправе задержать транспортное средство в случаях, установленных Кодексом РО об административных правонарушениях."},{"type":"paragraph","number":"2","text":"Задержание транспортного средства является мерой обеспечения и не должно использоваться как дополнительное не предусмотренное законом наказание."},{"type":"paragraph","number":"3","text":"Основание задержания объявляется водителю или владельцу при наличии такой возможности и фиксируется в материалах."}],"node_id":"41"},{"type":"article","number":"42","title":"Перемещение транспортного средства на специализированное место хранения","children":[{"type":"paragraph","number":"1","text":"Принудительное перемещение допускается, когда сохранение транспортного средства на месте противоречит безопасности, препятствует движению, дальнейшая эксплуатация незаконна либо иное прямо предусмотрено законом."},{"type":"paragraph","number":"2","text":"Если основание может быть немедленно устранено до фактического начала перемещения и дальнейшее управление является законным и безопасным, перемещение не производится, кроме случая обязательного задержания, прямо установленного законом."},{"type":"paragraph","number":"3","text":"При перемещении принимаются разумные меры к сохранности транспортного средства и находящегося в нем имущества."}],"node_id":"42"},{"type":"article","number":"43","title":"Возврат задержанного транспортного средства","children":[{"type":"paragraph","number":"1","text":"Транспортное средство подлежит возврату владельцу или законному пользователю после отпадения основания задержания, если оно не удерживается как вещественное доказательство, предмет конфискации либо по иному самостоятельному законному основанию."},{"type":"paragraph","number":"2","text":"Отказ в возврате должен быть основан на действующем правовом основании и может быть обжалован вышестоящему должностному лицу, прокурору или в суд."}],"node_id":"43"},{"type":"article","number":"44","title":"Государственная регистрация транспортных средств","children":[{"type":"paragraph","number":"1","text":"ГИБДД осуществляет государственную регистрацию транспортных средств, ведет регистрационный учет и выдает регистрационные документы и государственные регистрационные знаки."},{"type":"paragraph","number":"2","text":"Для регистрации лицо обязано подтвердить право собственности или иное законное основание владения транспортным средством, его идентификационные сведения и иные предусмотренные законом данные."},{"type":"paragraph","number":"3","text":"Отказ в регистрации допускается при отсутствии необходимых законных оснований, установленных признаках подделки документов или идентификационных обозначений либо в иных прямо установленных федеральным законом случаях."},{"type":"paragraph","number":"4","text":"Решение об отказе может быть обжаловано вышестоящему должностному лицу ГИБДД либо в суд."}],"node_id":"44"},{"type":"article","number":"45","title":"Государственные регистрационные знаки","children":[{"type":"paragraph","number":"1","text":"Государственный регистрационный знак присваивается транспортному средству при государственной регистрации."},{"type":"paragraph","number":"2","text":"Использование знака, выданного другому транспортному средству, подложного либо измененного с целью затруднить идентификацию, влечет последствия, установленные законом."},{"type":"paragraph","number":"3","text":"ГИБДД вправе изъять заведомо подложный регистрационный знак как предмет административного материала либо доказательство при наличии законного основания."}],"node_id":"45"},{"type":"article","number":"46","title":"Выдача водительских удостоверений","children":[{"type":"paragraph","number":"1","text":"ГИБДД организует проверку права граждан на управление транспортными средствами и выдачу водительских удостоверений соответствующих категорий."},{"type":"paragraph","number":"2","text":"Первоначальная выдача водительского удостоверения осуществляется после подтверждения личности, отсутствия установленного законом запрета и успешного прохождения предусмотренной проверки знаний и навыков управления."},{"type":"paragraph","number":"3","text":"Порядок проведения экзамена, перечень категорий и форма водительского удостоверения устанавливаются нормативным актом Правительства РО или Министерства внутренних дел в пределах федерального законодательства."},{"type":"paragraph","number":"4","text":"Отказ в выдаче должен быть мотивирован и может быть обжалован."}],"node_id":"46"},{"type":"article","number":"47","title":"Исполнение лишения права управления и восстановление права","children":[{"type":"paragraph","number":"1","text":"ГИБДД ведет учет лиц, лишенных права управления транспортными средствами, и обеспечивает исполнение вступивших в силу судебных актов."},{"type":"paragraph","number":"2","text":"По окончании срока лишения право управления восстанавливается при отсутствии другого действующего запрета и выполнении установленных законом условий."},{"type":"paragraph","number":"3","text":"ГИБДД не вправе продлевать срок лишения специального права внутренним решением."}],"node_id":"47"},{"type":"article","number":"48","title":"Контроль технического состояния транспортного средства","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД вправе проверить внешне выявляемое техническое состояние транспортного средства, если имеются признаки неисправности, при которой эксплуатация может быть запрещена."},{"type":"paragraph","number":"2","text":"При неисправности, создающей непосредственную угрозу безопасности, сотрудник вправе запретить дальнейшее движение и применить предусмотренную законом меру задержания транспортного средства."},{"type":"paragraph","number":"3","text":"Незначительная неисправность, не препятствующая безопасному следованию к месту ремонта, сама по себе не должна влечь задержание транспортного средства, если закон прямо не устанавливает иное."}],"node_id":"48"},{"type":"article","number":"49","title":"Изменение конструкции транспортного средства","children":[{"type":"paragraph","number":"1","text":"Существенное изменение конструкции, способное повлиять на безопасность движения, допускается в порядке, установленном федеральным законодательством."},{"type":"paragraph","number":"2","text":"ГИБДД вправе проверять соответствие таких изменений установленным требованиям и регистрационным сведениям."},{"type":"paragraph","number":"3","text":"Внутренний акт ГИБДД не может запрещать конструктивное изменение, которое прямо разрешено актом большей юридической силы."}],"node_id":"49"},{"type":"article","number":"50","title":"Специальные световые и звуковые сигналы","children":[{"type":"paragraph","number":"1","text":"ГИБДД осуществляет учет и контроль законности установки и использования специальных световых и звуковых сигналов на транспортных средствах."},{"type":"paragraph","number":"2","text":"Право использования таких сигналов предоставляется только в случаях и порядке, установленных федеральным законодательством и принятыми в соответствии с ним актами."},{"type":"paragraph","number":"3","text":"При выявлении незаконно установленного специального устройства ГИБДД вправе принять меры к его изъятию в порядке производства по делу об административном правонарушении."}],"node_id":"50"}]},{"type":"chapter","number":"VII","title":"ДОРОЖНО-ТРАНСПОРТНЫЕ ПРОИСШЕСТВИЯ​","children":[{"type":"article","number":"51","title":"Реагирование на дорожно-транспортное происшествие","children":[{"type":"paragraph","number":"1","text":"При получении сообщения о ДТП ГИБДД принимает меры к прибытию на место, обеспечению безопасности, организации движения и фиксации существенных обстоятельств, если присутствие ГИБДД требуется законом или обстоятельствами происшествия."},{"type":"paragraph","number":"2","text":"При наличии пострадавших приоритет имеют вызов медицинской помощи, оказание первой помощи и устранение продолжающейся угрозы жизни."},{"type":"paragraph","number":"3","text":"При необходимости сотрудник организует временное ограничение движения и охрану места происшествия."}],"node_id":"51"},{"type":"article","number":"52","title":"Обязанности сотрудника ГИБДД на месте ДТП","children":[{"type":"paragraph","text":"Сотрудник ГИБДД на месте ДТП вправе и обязан в пределах необходимости:","children":[{"type":"subparagraph","number":"1","text":"установить участников и очевидцев;"},{"type":"subparagraph","number":"2","text":"проверить документы и состояние водителей;"},{"type":"subparagraph","number":"3","text":"организовать освидетельствование при наличии оснований;"},{"type":"subparagraph","number":"4","text":"произвести фото- и видеофиксацию, измерения и схему происшествия;"},{"type":"subparagraph","number":"5","text":"зафиксировать повреждения и существенные следы;"},{"type":"subparagraph","number":"6","text":"получить объяснения;"},{"type":"subparagraph","number":"7","text":"установить относящиеся к происшествию дорожные знаки, разметку, сигналы и условия видимости;"},{"type":"subparagraph","number":"8","text":"выявить признаки административного правонарушения или преступления;"},{"type":"subparagraph","number":"9","text":"обеспечить сохранность доказательств до передачи материала компетентному органу."}]}],"node_id":"52"},{"type":"article","number":"53","title":"Освобождение проезжей части после ДТП","children":[{"type":"paragraph","number":"1","text":"Если транспортные средства создают существенное препятствие или угрозу, после достаточной фиксации их положения, повреждений и следов сотрудник вправе потребовать освободить проезжую часть."},{"type":"paragraph","number":"2","text":"До необходимой фиксации сотрудник не вправе без причины изменять обстановку, если это способно уничтожить существенные доказательства."},{"type":"paragraph","number":"3","text":"При непосредственной угрозе жизни, пожара или нового столкновения транспортные средства и предметы могут быть перемещены до полной фиксации в объеме, необходимом для устранения опасности."}],"node_id":"53"},{"type":"article","number":"54","title":"ДТП только с имущественным ущербом","children":[{"type":"paragraph","number":"1","text":"Если в ДТП отсутствуют пострадавшие, не повреждено государственное или чужое имущество помимо имущества самих участников и участники согласны относительно существенных обстоятельств, они вправе после достаточной фото- или видеофиксации освободить проезжую часть и урегулировать имущественный вопрос добровольно."},{"type":"paragraph","number":"2","text":"При споре об обстоятельствах, наличии признаков опьянения, оставлении места ДТП, отсутствии права управления либо ином существенном нарушении участники вправе вызвать ГИБДД, а в предусмотренных законом случаях обязаны это сделать."},{"type":"paragraph","number":"3","text":"Добровольное соглашение участников о возмещении ущерба не препятствует привлечению к административной ответственности за самостоятельно выявленное нарушение, если закон не предусматривает иное."}],"node_id":"54"},{"type":"article","number":"55","title":"Определение административно значимых обстоятельств ДТП","children":[{"type":"paragraph","number":"1","text":"ГИБДД устанавливает фактические обстоятельства, необходимые для решения вопроса об административной ответственности, и вправе определить нарушение правил дорожного движения, состоящее в причинной связи с ДТП."},{"type":"paragraph","number":"2","text":"Решение ГИБДД об административной ответственности не определяет окончательный размер гражданско-правового возмещения между участниками, если такой вопрос не урегулирован ими добровольно или не разрешен судом."}],"node_id":"55"},{"type":"article","number":"56","title":"ДТП с признаками преступления","children":[{"type":"paragraph","number":"1","text":"При наличии признаков преступления ГИБДД прекращает самостоятельное разрешение материала в соответствующей части и передает его компетентному органу по подследственности."},{"type":"paragraph","number":"2","text":"До передачи сотрудники вправе совершить неотложные действия, необходимые для спасения людей, задержания подозреваемого, сохранения доказательств и установления участников."},{"type":"paragraph","number":"3","text":"Передача уголовного материала не препятствует разрешению отдельного административного эпизода, если он юридически самостоятельный и такая процедура допускается законом."}],"node_id":"56"},{"type":"article","number":"57","title":"Материалы ДТП и их предоставление","children":[{"type":"paragraph","number":"1","text":"Материалы оформления ДТП должны позволять проверить существенные обстоятельства происшествия и происхождение доказательств."},{"type":"paragraph","number":"2","text":"Участники ДТП, их адвокаты, суд, прокуратура, следственный орган и иные уполномоченные лица вправе получать или истребовать материалы в объеме и порядке, предусмотренных федеральным законодательством."}],"node_id":"57"}]},{"type":"chapter","number":"VIII","title":"ПРЕСЛЕДОВАНИЕ, ПРИНУДИТЕЛЬНАЯ ОСТАНОВКА И СПЕЦИАЛЬНЫЕ ДОРОЖНЫЕ МЕРОПРИЯТИЯ​","children":[{"type":"article","number":"58","title":"Преследование транспортного средства","children":[{"type":"paragraph","number":"1","text":"ГИБДД вправе начать преследование, если водитель не выполнил законное требование об остановке, транспортное средство либо находящееся в нем лицо подлежит задержанию, водитель создает непосредственную опасность либо имеется другое предусмотренное законом основание."},{"type":"paragraph","number":"2","text":"В ходе преследования сотрудник по возможности повторяет требование об остановке и обозначает принадлежность служебного транспортного средства к полиции."},{"type":"paragraph","number":"3","text":"Продолжение погони должно соразмеряться с тяжестью основания и риском для иных участников движения. При очевидном превышении создаваемого погоней риска над необходимостью немедленного задержания руководитель или сотрудник вправе изменить тактику либо прекратить непосредственное преследование, сохранив розыскные меры."}],"node_id":"58"},{"type":"article","number":"59","title":"Переход к принудительной остановке","children":[{"type":"paragraph","number":"1","text":"Принудительная остановка допускается после неисполнения законного требования об остановке, если дальнейшее движение создает существенную опасность, лицо подлежит задержанию либо промедление объективно затруднит исполнение законной меры."},{"type":"paragraph","number":"2","text":"Повторное предупреждение не требуется, если транспортное средство используется как средство нападения, водитель создает непосредственную угрозу жизни, прорывает оцепление или охраняемый объект либо иная обстановка требует немедленного пресечения."},{"type":"paragraph","number":"3","text":"Сам факт неостановки не разрешает применение смертельной силы."}],"node_id":"59"},{"type":"article","number":"60","title":"Средства принудительной остановки","children":[{"type":"paragraph","number":"1","text":"Для принудительной остановки могут применяться служебные транспортные средства для блокирования, дорожные заграждения, устройства принудительной остановки, изменение организации движения и иные разрешенные законом специальные средства."},{"type":"paragraph","number":"2","text":"Контакт служебным транспортным средством допускается при необходимости прекратить опасное движение и должен осуществляться с учетом скорости, окружающей обстановки, наличия пассажиров и риска для посторонних лиц."},{"type":"paragraph","number":"3","text":"Огнестрельное оружие по транспортному средству может применяться только при самостоятельном наличии оснований для смертельной силы, предусмотренных Федеральным законом «О полиции». Стрельба исключительно по колесам с целью обычной остановки не образует самостоятельного основания применения оружия."}],"node_id":"60"},{"type":"article","number":"61","title":"Принудительное извлечение лица из транспортного средства","children":[{"type":"paragraph","number":"1","text":"После законной остановки сотрудник вправе потребовать водителя или пассажира выйти из транспортного средства при наличии оснований статьи 21 настоящего Федерального закона."},{"type":"paragraph","number":"2","text":"При отказе и наличии риска побега, сопротивления, уничтожения доказательств или иной существенной опасности допускается необходимая и соразмерная физическая сила или специальное средство."},{"type":"paragraph","number":"3","text":"После прекращения сопротивления интенсивность воздействия должна быть немедленно снижена."}],"node_id":"61"},{"type":"article","number":"62","title":"Контрольные посты и заградительные мероприятия","children":[{"type":"paragraph","number":"1","text":"ГИБДД вправе устанавливать временные контрольные посты и заградительные мероприятия при розыске транспортного средства или лица, массовом мероприятии, чрезвычайной ситуации, специальной профилактической операции, угрозе безопасности движения либо ином предусмотренном законом основании."},{"type":"paragraph","number":"2","text":"В пределах такого мероприятия допускается остановка транспортных средств для проверки документов и сведений, относящихся к цели мероприятия."},{"type":"paragraph","number":"3","text":"Полный обыск транспортного средства требует самостоятельного процессуального основания и не возникает автоматически из факта прохождения контрольного поста."}],"node_id":"62"},{"type":"article","number":"63","title":"Организованные транспортные колонны и сопровождение","children":[{"type":"paragraph","number":"1","text":"ГИБДД вправе организовывать сопровождение государственных кортежей, специальных перевозок, колонн транспортных средств и иных перевозок, требующих повышенных мер безопасности."},{"type":"paragraph","number":"2","text":"Сотрудники вправе временно ограничивать движение, перекрывать пересечения и требовать от иных водителей не вклиниваться в сопровождаемую колонну."},{"type":"paragraph","number":"3","text":"Ограничения применяются только в объеме, необходимом для безопасного прохождения колонны."}],"node_id":"63"},{"type":"article","number":"64","title":"Преимущество транспортных средств со специальными сигналами","children":[{"type":"paragraph","number":"1","text":"Транспортному средству, законно использующему специальные световые и звуковые сигналы при выполнении неотложного служебного задания, предоставляется преимущество в пределах правил дорожного движения."},{"type":"paragraph","number":"2","text":"Использование преимущества не освобождает водителя специального транспортного средства от обязанности принимать разумные меры к безопасности."},{"type":"paragraph","number":"3","text":"Сотрудник ГИБДД вправе пресечь явно опасное или неправомерное использование специальных сигналов, если вмешательство не создает большей непосредственной угрозы."}],"node_id":"64"},{"type":"article","number":"65","title":"Специальные профилактические мероприятия","children":[{"type":"paragraph","number":"1","text":"По решению Начальника ГИБДД, его заместителя или иного уполномоченного руководителя могут проводиться специальные профилактические мероприятия, направленные на выявление опьянения, транспортных средств в розыске, подложных регистрационных знаков, опасных технических неисправностей, грубых нарушений правил движения и иных конкретных рисков."},{"type":"paragraph","number":"2","text":"Мероприятие должно иметь определенную цель и не предоставляет сотрудникам полномочий, отсутствующих в федеральном законодательстве."},{"type":"paragraph","number":"3","text":"Результаты мероприятия оформляются в обычном процессуальном порядке."}],"node_id":"65"},{"type":"article","number":"66","title":"Дорожные работы, опасные участки и обязательные предписания","children":[{"type":"paragraph","number":"1","text":"При обнаружении опасного состояния дороги, неработающего средства организации движения, препятствия или иных условий, создающих угрозу, ГИБДД вправе принять временные меры безопасности и направить владельцу дороги или ответственному органу обязательное законное предписание об устранении нарушения в пределах предоставленной компетенции."},{"type":"paragraph","number":"2","text":"При непосредственной угрозе ГИБДД вправе ограничить движение до устранения опасности."},{"type":"paragraph","number":"3","text":"Неисполнение законного письменного предписания влечет ответственность в порядке, установленном Кодексом РО об административных правонарушениях."}],"node_id":"66"}]},{"type":"chapter","number":"IX","title":"ВЗАИМОДЕЙСТВИЕ, НАДЗОР, ОБЖАЛОВАНИЕ И ОТВЕТСТВЕННОСТЬ​","children":[{"type":"article","number":"67","title":"Взаимодействие с иными подразделениями МВД РО","children":[{"type":"paragraph","number":"1","text":"ГИБДД и иные подразделения МВД РО взаимно содействуют друг другу в задержании лиц, розыске транспортных средств, охране места происшествия, обеспечении массовых мероприятий и иных законных действиях."},{"type":"paragraph","number":"2","text":"Обычное подразделение полиции вправе остановить транспортное средство по основаниям Федерального закона «О полиции», однако специальный дорожный контроль и систематическое производство по дорожным нарушениям осуществляются ГИБДД, если закон не устанавливает иное."},{"type":"paragraph","number":"3","text":"ГИБДД вправе передать задержанное лицо сотруднику МВД РО вместе с существенными основаниями и материалами, если дальнейшее производство не относится к дорожной компетенции."}],"node_id":"67"},{"type":"article","number":"68","title":"Взаимодействие со Следственным комитетом","children":[{"type":"paragraph","number":"1","text":"ГИБДД исполняет законные поручения Следственного комитета по конкретному уголовному делу в пределах своей компетенции, включая розыск транспортного средства, установление маршрута, обеспечение остановки, охрану места ДТП и содействие при следственном действии."},{"type":"paragraph","number":"2","text":"Поручение Следственного комитета не предоставляет ГИБДД право принимать процессуальное решение, отнесенное к исключительной компетенции следователя, прокурора или суда."}],"node_id":"68"},{"type":"article","number":"69","title":"Взаимодействие с Федеральной службой безопасности","children":[{"type":"paragraph","text":"ГИБДД оказывает ФСБ РО предусмотренное законом содействие при розыске опасного транспортного средства, обеспечении контртеррористического мероприятия, охране маршрута, перекрытии движения и иных действиях в сфере государственной безопасности, сохраняя установленную законом компетенцию каждого органа."}],"node_id":"69"},{"type":"article","number":"70","title":"Взаимодействие с прокуратурой","children":[{"type":"paragraph","number":"1","text":"Прокуратура осуществляет надзор за соблюдением ГИБДД федерального законодательства в пределах своих полномочий."},{"type":"paragraph","number":"2","text":"ГИБДД обязана предоставлять прокурору законно истребованные административные материалы, записи, регистрационные сведения и иные документы."},{"type":"paragraph","number":"3","text":"Прокурорский надзор не является повседневным административным руководством ГИБДД."},{"type":"paragraph","number":"4","text":"Решение прокурора, принятое при обязательном рассмотрении задержания государственного служащего, обязательно для сотрудников ГИБДД в пределах федерального законодательства."}],"node_id":"70"},{"type":"article","number":"71","title":"Взаимодействие с судами","children":[{"type":"paragraph","number":"1","text":"ГИБДД направляет в суд материалы, для которых Кодекс РО об административных правонарушениях устанавливает обязательный судебный порядок, и исполняет вступившие в силу судебные акты в пределах своей компетенции."},{"type":"paragraph","number":"2","text":"ГИБДД обязана предоставить суду истребованные материалы, необходимые для проверки законности дорожного административного решения, лишения права управления, эвакуации или иного действия."},{"type":"paragraph","number":"3","text":"Сотрудник ГИБДД не вправе игнорировать, отменять или пересматривать вступивший в силу судебный акт."}],"node_id":"71"},{"type":"article","number":"72","title":"Взаимодействие с медицинскими, спасательными и дорожными службами","children":[{"type":"paragraph","number":"1","text":"ГИБДД взаимодействует с медицинскими и спасательными службами при ДТП, освидетельствовании и иных случаях угрозы жизни и здоровью."},{"type":"paragraph","number":"2","text":"ГИБДД взаимодействует с владельцами дорог, коммунальными и аварийными службами при устранении препятствий, повреждений и иных угроз безопасности дорожного движения."},{"type":"paragraph","number":"3","text":"Требование сотрудника ГИБДД к такой службе должно относиться к его компетенции и быть направлено на конкретную законную цель."}],"node_id":"72"},{"type":"article","number":"73","title":"Взаимодействие с Вооруженными Силами и военными объектами","children":[{"type":"paragraph","number":"1","text":"При движении военных колонн, перевозке вооружения или иных специальных военных перевозках ГИБДД вправе обеспечивать сопровождение и регулирование движения по согласованию с уполномоченным военным должностным лицом."},{"type":"paragraph","number":"2","text":"Доступ ГИБДД на военную или иную режимную территорию осуществляется с учетом установленного режима, кроме неотложного пресечения непосредственной угрозы жизни либо исполнения иного акта, прямо предоставляющего право доступа."}],"node_id":"73"},{"type":"article","number":"74","title":"Ведомственный контроль","children":[{"type":"paragraph","number":"1","text":"Начальник ГИБДД, его заместители и иные уполномоченные руководители вправе проверять законность и качество работы сотрудников, истребовать материалы, отменять незаконное внутреннее решение, назначать служебную проверку и применять дисциплинарные меры в пределах компетенции."},{"type":"paragraph","number":"2","text":"Ведомственный контроль не может использоваться для сокрытия доказательств, уничтожения жалобы либо давления на сотрудника с целью вынести заведомо незаконное административное решение."}],"node_id":"74"},{"type":"article","number":"75","title":"Обжалование действий и решений ГИБДД","children":[{"type":"paragraph","number":"1","text":"Действие, бездействие или решение сотрудника ГИБДД может быть обжаловано вышестоящему должностному лицу, в прокуратуру или в суд в порядке, установленном федеральным законодательством."},{"type":"paragraph","number":"2","text":"Ведомственный пересмотр административного наказания производится по правилам Кодекса РО об административных правонарушениях."},{"type":"paragraph","number":"3","text":"Жалоба на действие, не являющееся административным наказанием, рассматривается по общим правилам процессуального законодательства."},{"type":"paragraph","number":"4","text":"Подача жалобы сама по себе не приостанавливает действующее законное требование или меру, если компетентное должностное лицо, прокурор или суд не распорядится иначе."}],"node_id":"75"},{"type":"article","number":"76","title":"Ответственность сотрудника ГИБДД","children":[{"type":"paragraph","number":"1","text":"Сотрудник ГИБДД несет дисциплинарную, административную, гражданско-правовую и уголовную ответственность за виновное незаконное действие или бездействие."},{"type":"paragraph","number":"2","text":"Заведомо незаконная остановка с целью давления, фальсификация дорожного материала, внесение ложных регистрационных сведений, незаконное лишение возможности управлять транспортом, необоснованная эвакуация, незаконное освидетельствование, сокрытие обязательной записи и иное злоупотребление полномочиями влекут ответственность в соответствии с законом."},{"type":"paragraph","number":"3","text":"Отмена административного решения вышестоящим должностным лицом, прокурором или судом сама по себе не доказывает вину сотрудника."}],"node_id":"76"},{"type":"article","number":"77","title":"Возмещение вреда","children":[{"type":"paragraph","text":"Вред, причиненный незаконным действием ГИБДД, возмещается в порядке, установленном федеральным законодательством. Возмещение вреда государством не препятствует решению вопроса об ответственности виновного должностного лица. Нормативно-правовой акт подписан Премьер-министром РО 25.08.2026 Марк Брагин ​"}],"node_id":"77"}]}]};
